{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Trocade, a cyclic hydantoin MMP inhibitor with lipophilic cyclohexylmethyl and a polar acidic/hydroxamate side chain, has an absolute oral bioavailability of 43% in healthy volunteers, supporting that the query's cyclic imide/urea scaffold with cyclohexyl groups and an acidic side chain can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Omapatrilat, an acidic peptidomimetic containing a free carboxylic acid and amide/lactam motifs, has an absolute oral bioavailability of about 31% in healthy subjects, supporting F >= 20% for the query's acidic, amide-rich structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tiopronin, which contains a glycine amide and carboxylic acid substructure similar to the query's side chain, has an absolute oral bioavailability of 63%, indicating that this polar acidic motif is not inherently incompatible with F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Inogatran, a peptide-like thrombin inhibitor with a basic guanidine and carboxylic acid, has <5% oral bioavailability; however, the query lacks the basic center, limiting the transferability of this low-F result.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "Alvimopan has only about 6% oral bioavailability, but its poor absorption is associated with zwitterionic character from a basic amine plus carboxylic acid, a feature not present in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an acidic barbiturate-like glycine amide with two N-cyclohexyl groups. The most transferable experimental evidence comes from moderately absorbed acidic and cyclic-urea peptidomimetics (Trocade 43%, omapatrilat ~31%, tiopronin 39-63%), all above the 20% threshold. The low-F analogues (inogatran, alvimopan) owe their poor absorption to basic/zwitterionic features absent in the query. Therefore, F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct pharmacokinetic data are available for the query molecule.",
    "No exact structural analogue with measured oral bioavailability was retrieved.",
    "Intestinal permeability and efflux-transporter behavior of the barbiturate-glycine acid scaffold are unknown.",
    "Potential first-pass metabolism or prodrug considerations for the free carboxylic acid are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

